    x.fillText("TIPS AND COUNTING",W/2,y); y+=100;
    x.fillStyle="#c9bfa8"; x.font="400 38px Arial,sans-serif";
    x.fillText(n.toLocaleString()+" creators getting funded.",W/2,y); y+=70;
    x.fillText("The machine funds its own.",W/2,y);
